def find_minimal_edit(s_in, s_out):
    """Find the minimal change from s_in to s_out"""
    # Find first difference
    min_len = min(len(s_in), len(s_out))

    # Check for insertions/deletions
    if len(s_in) != len(s_out):
        # Look for a single character insertion/deletion
        if len(s_in) + 1 == len(s_out):
            # Insertion case - check if s_out is s_in with one char inserted
            for i in range(len(s_in) + 1):
                if s_in[:i] + s_in[i:] == s_out:
                    return (s_in[i], s_out[i], i)
        elif len(s_in) == len(s_out) + 1:
            # Deletion case
            for i in range(len(s_out)):
                if s_in[:i] + s_in[i+1:] == s_out:
                    return (s_in[i], "", i)

    # Character replacement case
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            return (s_in[i], s_out[i], i)

    # If we reach here, check if one string is longer
    if len(s_in) < len(s_out):
        return (s_in[-1], s_out[-1], len(s_in)-1) if len(s_in) > 0 else (None, s_out[-1], 0)
    elif len(s_in) > len(s_out):
        return (s_in[-1], "", len(s_out)-1) if len(s_out) > 0 else (s_in[-1], "", 0)

    return ("", "", -1)  # No change

