def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit from s_in to s_out."""
    # Find first difference
    min_len = min(len(s_in), len(s_out))

    # Check for character replacements
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            return (s_in[i], s_out[i], i)

    # If we reach here, check for insertions/deletions
    if len(s_in) < len(s_out):
        # Insertion case
        for i in range(len(s_in)):
            if s_in[:i] + s_in[i:] == s_out:
                return (s_in[i], s_out[i], i)
        return (s_in[-1], s_out[-1], len(s_in)-1) if len(s_in) > 0 else (None, s_out[-1], 0)
    elif len(s_in) > len(s_out):
        # Deletion case
        for i in range(len(s_out)):
            if s_in[:i] + s_in[i+1:] == s_out:
                return (s_in[i], "", i)
        return (s_in[-1], "", len(s_out)-1) if len(s_out) > 0 else (s_in[-1], "", 0)

    return ("", "", -1)  # No change

def propose_rule_candidates(s_in, s_out):
    """Propose rule candidates from a changed pair."""
    # For this simplified version, we'll focus on character-level changes
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)

    # Return a few candidates: most specific first
    candidates = []

    # Most specific: single character replacement
    if old_sub and new_sub != "":
        candidates.append((old_sub, new_sub))

    # Also consider larger patterns if they exist
    # Simple pattern matching - check for repeated patterns
    if len(s_in) >= 2 and len(s_out) >= 2:
        # Try to find substring patterns
        for length in range(2, min(len(s_in), len(s_out)) + 1):
            if length <= len(s_in) and length <= len(s_out):
                # Check if substring of length matches
                substr_in = s_in[pos:pos+length]
                substr_out = s_out[pos:pos+length]
                if substr_in != substr_out:
                    candidates.append((substr_in, substr_out))

    # Add general pattern
    candidates.append((s_in, s_out))

    # Remove duplicates and return
    seen = set()
    unique_candidates = []
    for cand in candidates:
        if cand not in seen:
            seen.add(cand)
            unique_candidates.append(cand)

    return unique_candidates

def apply_rules(strings, rules):
    """Apply a sequence of rules to a list of strings."""
    result = strings[:]
    for pattern, replacement in rules:
        result = [s.replace(pattern, replacement) for s in result]
    return result

def score_rules(inputs, outputs, rules):
    """Score how well rules perform on the given inputs/outputs."""
    results = apply_rules(inputs, rules)
    score = sum(1 for i, r in enumerate(results) if r == outputs[i]) / len(inputs)
    return score

